import {TOPICS,EFFECTS,RESPONSIBILITIES,projectResponsibilities,chosen,statusLabel,governanceLabel,governanceCurrent,decisionCurrent,impactCurrent,decisionSourceChanged,criterion,decisionFindings,decisionMilestones,decisionReviewCurrent,decisionHandoffCurrent,conflictResolved,potentialDecisionConflicts,decisionGuidance,decisionPatterns,proposedAlternative} from './decisions-domain.js';
import {edges as referenceEdges} from './model.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={layers:'m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5',work:'M4 7h16v14H4zM8 7V3h8v4M4 12h16',model:'M3 3h6v6H3zM15 15h6v6h-6zM6 9v9h9',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',file:'M5 3h9l5 5v13H5zM14 3v6h5M8 13h8m-8 4h6',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3zM12 6v15',cursor:'m5 3 14 10-7 1-3 7z',lock:'M5 10h14v11H5zM8 10V7a4 4 0 0 1 8 0v3',plus:'M12 5v14M5 12h14',arrow:'M4 12h16m-6-6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',play:'m8 4 12 8-12 8z',pause:'M8 4v16M16 4v16'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`,btn=(action,label,style='',attrs='')=>`<button type="button" class="r-btn ${style}" data-d-action="${action}" ${attrs}>${label}</button>`;
const store=createProjectStore(),params=new URLSearchParams(location.search),ui={tab:['work','model','validate','output'].includes(params.get('tab'))?params.get('tab'):'work',stage:'compare',comparisonView:'options',criterion:null,selected:params.get('decision')||null,alternative:null,compare:[],node:null,layers:readPerspectives(3,['requirement','driver','alternative','responsibility']),base:true,flow:false,cursor:cursorPreference(),wide:false,menu:false,filter:'gaps',proposal:null,busy:false,dirty:false,modal:null,step:0,lastFocus:null};
let project,formState,tipTimer,toastTimer,resizeTimer;
document.body.classList.add('requirements-app','decisions-app');
const decision=()=>project?.decisions.records.find(d=>d.id===ui.selected),option=()=>ui.proposal?.record||decision()?.alternatives.find(a=>a.id===ui.alternative)||chosen(decision())||decision()?.alternatives[0];
const stateBadge=d=>`<span class="d-status ${d.status}">${statusLabel(d)}</span>`,effect=v=>`<span class="d-effect ${v?.effect||'unknown'}">${EFFECTS.find(e=>e[0]===v?.effect)?.[1]||'Needs evidence'}</span>`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function route(){savePerspectives(3,ui.layers);const p=new URLSearchParams({chapter:'3',tab:ui.tab});if(ui.selected)p.set('decision',ui.selected);window.history.replaceState({},'',projectURL(location.pathname+'?'+p))}
function syncSelection(){if(!decision())ui.selected=project.decisions.records[0]?.id||null;const d=decision();if(!d?.alternatives.some(a=>a.id===ui.alternative))ui.alternative=d?.selectedAlternativeId||d?.alternatives[0]?.id||null;if(!ui.compare.every(id=>d?.alternatives.some(a=>a.id===id))||ui.compare.length<Math.min(2,d?.alternatives.length||0))ui.compare=d?.alternatives.slice(0,2).map(a=>a.id)||[];}
async function load(){hideTip();$('#app').innerHTML='<main class="r-loading"><p class="r-kicker">AIW V5 / Private project</p><h1>Opening architectural decisions.</h1><p>Opening the saved project…</p></main>';try{project=(await store.load()).document;syncSelection();render()}catch(e){$('#app').innerHTML=`<main class="r-loading"><h1>Your project is unavailable.</h1><p>${esc(e.message)}</p>${btn('reload','Try again','primary')}</main>`}}
async function send(type,payload={},message='Decision saved.'){
 if(ui.busy)return false;ui.busy=true;$('#d-save-state').textContent='Saving…';$('.d-dialog')?.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);
 try{const result=await store.command({type:'decision.'+type,payload});project=result.document;if(result.selected)ui.selected=result.selected;ui.proposal=null;ui.node=null;syncSelection();ui.dirty=false;closeDialog(true);render();toast(message);return true}
 catch(e){$('#d-save-state').textContent='Not saved';const el=$('#d-form-error')||$('#d-page-error');el.hidden=false;el.innerHTML=esc(e.message)+(e.conflict?' '+btn('refresh','Load latest project'):'');el.scrollIntoView({block:'nearest'});toast('Your input is preserved. Review the message and try again.');return false}
 finally{ui.busy=false;$('.d-dialog')?.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false)}
}
function render(){const restoreFocus=rememberRailFocus();document.body.dataset.workspaceTab=ui.tab;hideTip();route();const ms=decisionMilestones(project),done=ms.filter(m=>m.done).length,pct=Math.round(done/ms.length*100),next=ms.find(m=>!m.done),d=decision();
 $('#app').innerHTML=`<header class="r-topbar"><a class="r-brand" href="/?chapter=1" aria-label="AIW home"><span>${icon('layers')}</span><b>aiw</b><sup>V5</sup></a><span class="r-brand-caption">Intelligent Architecture Workbench</span><div class="r-top-status"><span id="d-save-state" role="status">Saved to your private project</span><span class="r-private">${icon('lock')}Private workspace</span></div>${btn('menu',icon('menu'),'r-mobile-menu','aria-label="Toggle chapter navigation" aria-expanded="'+ui.menu+'"')}</header><div class="r-shell"><aside class="r-sidebar ${ui.menu?'open':''}" aria-label="Project navigation"><p class="r-kicker">Your reference project</p><div class="r-project"><strong>Bank Payment Journey</strong><small>Requirements ${project.contentVersion} · Quality ${project.quality.version} · Decisions ${project.decisions.version}</small></div><p class="r-kicker">Architecture journey</p><nav>${[[1,'Requirements','Trace the required behaviour'],[2,'Quality drivers','Set measurable expectations'],[3,'Decisions','Compare and record choices'],[4,'Logical application','Define responsibilities'],[5,'Application realisation','Explore implementations'],[6,'Logical technology','Define supporting capabilities'],[7,'Technology realization','Compare and record technology choices'],[8,'Interfaces & Data','Define contracts and data ownership'],[9,'Security','Design controls and review risk'],[10,'Deployment / Runtime','Place and operate the architecture'],[11,'Review & Realize','Review the design and prepare delivery']].map(([n,t,s])=>n<=11?`<a class="r-chapter ${n===3?'current':''}" href="/?chapter=${n}" aria-current="${n===3?'step':'false'}"><span>${String(n).padStart(2,'0')}</span><span><b>${t}</b><small>${s}</small></span></a>`:`<div class="r-chapter unavailable"><span>06</span><span><b>${t}</b><small>${s}</small></span></div>`).join('')}</nav>${explorationRail(chapterPerspectives[3],ui.layers,'data-d-layer','data-d-layers-all',3)}<div class="r-side-progress"><p class="r-kicker">Chapter 3 readiness</p>${ms.map(m=>`<button class="r-milestone" data-d-milestone="${m.id}"><span>${m.done?'✓':'○'}</span><span class="r-milestone-copy">${m.name}<small>${esc(m.detail)}</small></span></button>`).join('')}</div><p class="r-side-note">An explicit choice.<br>A reason you can follow.</p></aside><main class="r-main" id="workspace"><div class="r-heading"><div><p class="r-breadcrumb">Bank Payment Journey <span>/</span> Chapter 03</p><h1>${{work:'Make the reasoning visible.',model:'Preview the impact of a choice.',validate:'Challenge the decision, keep the evidence.',output:'Decisions the model can carry forward.'}[ui.tab]}</h1><p>Architecture decisions · Alternatives, consequences, and a continuous trail</p></div><div class="r-progress"><div><span>Chapter 3 readiness</span><b>${pct}%</b></div><div class="r-progress-track" role="progressbar" aria-label="Chapter 3 readiness" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div><small>${done} of 6 milestones · Governance tracked separately</small></div></div><div class="r-workspace-bar"><nav class="r-tabs" aria-label="Chapter surfaces">${[['work','Work','work'],['model','Model','model'],['validate','Validate','shield'],['output','Output','file']].map(([id,t,ic])=>`<button data-d-tab="${id}" class="${ui.tab===id?'active':''}" aria-current="${ui.tab===id?'page':'false'}">${icon(ic)}${t}</button>`).join('')}</nav><div class="r-where"><span>Ch. 03 / ${ui.tab[0].toUpperCase()+ui.tab.slice(1)}</span><strong>${pct}%</strong>${btn('next','Next: '+(next?.name||'Open Chapter 4')+icon('arrow'),'next-button')}</div></div><div id="d-page-error" class="r-error" role="alert" hidden></div><div class="r-assistant-bar"><div><span class="r-kicker">Chapter 03 / ${ui.tab}</span><span>${d?d.id+' · '+statusLabel(d):'Project context'}</span></div><nav aria-label="Contextual assistance">${btn('sol',icon('spark')+'Sol')}${btn('mind',icon('book')+'Mind Factory')}${btn('cursor',icon('cursor')+'Cursor','','aria-pressed="'+ui.cursor+'"')}</nav></div><div class="d-question-bar"><label><span>Design question</span><select id="d-question-select">${project.decisions.records.map(d=>`<option value="${d.id}" ${ui.selected===d.id?'selected':''}>${d.id} · ${esc(d.question)}</option>`).join('')||'<option>No decisions yet</option>'}</select></label>${btn('new-question',icon('plus')+'New question')}</div><div class="r-studio ${ui.wide?'r-wide':''}"><section class="r-surface" aria-label="${ui.tab} workspace">${ui.tab==='work'?work():ui.tab==='model'?model():ui.tab==='validate'?validation():output()}</section><aside id="d-inspector" class="r-inspector" aria-label="Decision context inspector" tabindex="-1">${inspector()}</aside></div><footer class="r-footer"><span>AIW V5 · Architect acceptance and governance approval remain distinct.</span><button data-d-action="about">Rule-based guidance · About this chapter</button></footer></main></div><div id="d-dialog-host"></div>`;
 if(ui.tab==='model')drawMap();
refineWorkspace(ui.tab,{chapter:3,id:ui.node&&!ui.node.startsWith('alternative:')?ui.node.split(':')[1]:ui.selected});restoreFocus();
}
function work(){return `<div class="r-section-tabs" aria-label="Decision work stages">${[['inputs','Inputs & question'],['compare','Compare alternatives'],['record','Record & review']].map(([id,t])=>`<button data-d-stage="${id}" aria-pressed="${ui.stage===id}">${t}</button>`).join('')}</div>${ui.stage==='inputs'?inputs():ui.stage==='record'?record():comparison()}`}
function inputs(){const d=decision(),reviewed=project.decisions.intake?.sourceVersion===project.contentVersion&&project.decisions.intake?.qualityVersion===project.quality.version;return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">Chapters 1 / 2 → Chapter 3</p><h2>Start with the choice the design must make.</h2></div>${btn('review-inputs',reviewed?'Inputs reviewed':'Mark inputs reviewed','primary')}</div>${d?`<p>${esc(d.context)}</p><div class="r-actions">${btn('edit-question','Edit question & links')}</div><p class="d-origin">${d.origin==='reference'?'Illustrative reference question':'User-authored question'} · ${esc(d.source)}</p><h3>Requirements behind ${d.id}</h3><div class="d-source-list">${d.requirementIds.map(id=>{const a=project.artefacts.find(a=>a.id===id);return a?`<a href="/?chapter=1&tab=work&artefact=${id}"><b>${id}</b><span>${esc(a.title)}</span><small>${a.confirmed?'Confirmed':'Unconfirmed source'}</small></a>`:`<p class="r-error">Missing ${id}</p>`}).join('')||'<p>No requirements linked yet.</p>'}</div><h3>Quality drivers used as comparison criteria</h3><div class="d-source-list">${d.driverIds.map(id=>{const c=criterion(project,d,id);return c?`<a href="/?chapter=2&tab=model&driver=${id}"><b>${id} · ${c.priority}</b><span>${esc(c.title)}</span><small>${esc(c.measure)} · ${c.confirmed?'Target confirmed':'Target assumption'}</small></a>`:`<p class="r-error">Missing ${id}</p>`}).join('')||'<p>No quality drivers linked yet.</p>'}</div>`:'<p>Create a design question, then link its requirements and quality drivers.</p>'}<div class="r-reference-note">Reference comparisons are starting points. Numerical targets remain the assumptions recorded in Chapter 2.</div></article>`}
function comparison(){const d=decision();if(!d)return empty();const pair=ui.compare.map(id=>d.alternatives.find(a=>a.id===id)).filter(Boolean),criterionId=d.driverIds.includes(ui.criterion)?ui.criterion:d.driverIds[0];
 return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">${d.id} / Revision ${d.revision}</p><h2>${esc(d.question)}</h2></div>${stateBadge(d)}</div><nav class="f-subview-tabs" aria-label="Decision comparison view">${[['options','Alternatives'],['evidence','Quality evidence']].map(([id,label])=>`<button type="button" class="r-btn" data-d-comparison-view="${id}" aria-pressed="${ui.comparisonView===id}">${label}</button>`).join('')}</nav>${d.alternatives.length>2?`<div class="r-form-grid">${[0,1].map(i=>`<label class="r-field"><span>${i?'Second':'First'} comparison option</span><select data-d-compare="${i}">${d.alternatives.map(a=>`<option value="${a.id}" ${ui.compare[i]===a.id?'selected':''}>${a.id} · ${esc(a.title)}</option>`).join('')}</select></label>`).join('')}</div>`:''}${ui.comparisonView==='options'?`<div class="d-options">${pair.map(a=>optionCard(d,a)).join('')}</div><div class="r-actions">${btn('new-alternative',icon('plus')+'Add alternative')}${btn('edit-question','Edit question & links')}</div>`:`<p class="r-note">Each linked driver supplies a criterion. Effects are explained with reasons and evidence. No score or automatic winner is calculated.</p>${d.driverIds.length?`<label class="f-criterion-picker"><span>Comparison criterion</span><select data-d-criterion>${d.driverIds.map(id=>{const c=criterion(project,d,id);return `<option value="${id}" ${criterionId===id?'selected':''}>${id} · ${esc(c?.title||'Missing driver')}</option>`}).join('')}</select></label>`:'<div class="r-reference-note">Link quality drivers to define meaningful comparison criteria.</div>'}${[criterionId].filter(Boolean).map(id=>{const c=criterion(project,d,id);return c?`<section class="d-criterion"><header><span>${c.id} · ${c.priority}</span><h3>${esc(c.title)}</h3><p>${esc(c.measure)}</p><small>${c.confirmed?'Confirmed target':'Editable target assumption in Chapter 2'}</small></header><div class="d-assessments">${pair.map(a=>{const v=a.assessments[id];return `<article><small>${a.id} · ${esc(a.title)}</small>${effect(v)}<p>${esc(v?.reason||'Comparison reason missing.')}</p><p class="d-evidence"><b>Basis / evidence</b>${esc(v?.evidence||'Not recorded. This judgement needs support.')}</p><button type="button" class="r-btn" data-d-edit-option="${a.id}" data-step="1">Edit comparison</button></article>`}).join('')}</div></section>`:''}).join('')}`}</article>`;
}
function optionCard(d,a){return `<article class="d-option ${d.selectedAlternativeId===a.id?'chosen':''}" data-d-insight="alternative:${a.id}"><div class="d-option-meta"><span>${a.id}</span><span>${d.selectedAlternativeId===a.id?'Working choice':'Alternative'}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><details class="f-disclosure"><summary>Benefits and trade-offs</summary><dl><div><dt>Benefit</dt><dd>${esc(a.benefits||'Not recorded')}</dd></div><div><dt>Cost / trade-off</dt><dd>${esc(a.costs||'Not recorded')}</dd></div></dl></details><div class="r-actions"><button type="button" class="r-btn primary" data-d-preview="${a.id}">Preview impact ${icon('arrow')}</button><button type="button" class="r-btn" data-d-edit-option="${a.id}">Edit</button></div><button type="button" class="d-choice-button" data-d-choose="${a.id}" ${d.selectedAlternativeId===a.id?'disabled':''}>${d.selectedAlternativeId===a.id?'✓ Current working choice':'Use as working choice'}</button></article>`}
function record(){const d=decision();if(!d)return empty();const a=chosen(d);return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">${d.id} / Revision ${d.revision}</p><h2>${esc(d.question)}</h2></div>${stateBadge(d)}</div><div class="d-state-path"><span class="${a?'done':''}">1 · Working choice</span><span class="${['recorded','accepted'].includes(d.status)?'done':''}">2 · Recorded decision</span><span class="${d.status==='accepted'?'done':''}">3 · Architect accepted</span></div><div class="d-record-choice"><small>Preferred alternative</small><h3>${a?esc(a.title):'No working choice yet'}</h3><p>${esc(d.rationale||'Explain why this choice best addresses the linked requirements and quality drivers, and why the alternatives were not selected.')}</p></div><div class="r-actions">${btn('edit-question','Edit rationale & context','primary')}${d.status==='draft'?btn('record','Record decision'):d.status==='recorded'?btn('accept','Review architect acceptance','gold'):d.status==='accepted'?btn('model','Review model impact','gold'):''}</div><details class="f-disclosure"><summary>${d.assumptionsResolved?'Assumptions and risk treatment':'Open assumptions and risk treatment'}</summary><dl class="d-record-details"><div><dt>Assumptions</dt><dd>${esc(d.assumptions||'None recorded')}<small>${d.assumptionsResolved?'Confirmed: '+esc(d.assumptionEvidence):'Open assumptions'}</small></dd></div><div><dt>Risks</dt><dd>${esc(d.risks||'None recorded')}</dd></div><div><dt>Treatment</dt><dd>${esc(d.mitigation||'Not recorded')}</dd></div><div><dt>Owner / source</dt><dd>${esc(d.owner)} · ${esc(d.source)}</dd></div></dl></details><details class="f-disclosure"><summary>Governance · ${governanceLabel(d,project)}</summary><section class="d-governance"><p class="r-kicker">Separate review / Governance</p><h3>${governanceLabel(d,project)}</h3><p>Architect acceptance records the design choice. Governance approval requires a separate review outcome and supporting evidence.</p>${d.governance?`<p>${esc(d.governance.reviewer)} · ${esc(d.governance.evidence)}</p>`:''}${btn('governance','Record governance review')}${btn('supersede','Supersede decision')}</section></details><details class="f-disclosure"><summary>Recorded revisions · ${d.history.length}</summary>${revisionHistory(d)}</details><details class="f-disclosure"><summary>Decision conflicts · ${project.decisions.conflicts.length}</summary>${conflicts()}${btn('new-conflict','Record a conflict')}</details></article>`}
function revisionHistory(d){return [...d.history].reverse().map(h=>`<details class="d-history"><summary><span>r${h.revision} · ${esc(h.event)}</span><small>${new Date(h.at).toLocaleDateString('en-GB')}</small></summary><p>${esc(h.alternative||'No alternative selected')}</p><p>${esc(h.rationale||'No rationale recorded')}</p><small>${h.requirementIds.join(', ')} · ${h.driverIds.join(', ')}</small></details>`).join('')||'<p class="r-note">Recording and acceptance preserve the choice and rationale. A later edit creates a working revision and makes earlier model impacts inactive.</p>'}
function conflicts(){return project.decisions.conflicts.map(c=>`<article class="d-conflict"><small>${c.id} · ${c.decisionIds.join(' / ')}</small><h3>${esc(c.title)}</h3><p>${conflictResolved(project,c)?'Resolved':c.status==='resolved'?'Changed decision — review resolution':'Open conflict'}${c.resolution?' · '+esc(c.resolution):''}</p><button type="button" class="r-btn" data-d-conflict="${c.id}">Review conflict</button></article>`).join('')||'<p class="r-note">No conflicts recorded.</p>'}
function model(){const d=decision(),a=option();if(!d)return empty();return `<article class="r-card r-map-card d-map-card"><div class="r-card-head"><div><p class="r-kicker">${d.id} / Decision-impact map</p><h2>${esc(d.question)}</h2></div>${window.aiwChapterModels?.has?.(3)?`<button class="r-btn" data-cm-open="3" title="Return to this chapter's own architecture models">${icon('model')}Chapter 3 models</button>`:''}${btn('wide',icon('model'),'icon-only','aria-label="'+(ui.wide?'Restore inspector beside map':'Widen canvas')+'"')}</div><div class="d-alternative-strip">${d.alternatives.map(o=>`<button type="button" data-d-map-option="${o.id}" aria-pressed="${!ui.proposal&&a?.id===o.id}" data-d-insight="alternative:${o.id}"><small>${o.id} ${d.selectedAlternativeId===o.id?'· Working choice':''}</small><b>${esc(o.title)}</b></button>`).join('')||'<p>Add alternatives in Work to explore their impact.</p>'}</div>${a?`<section class="d-preview-band"><div><small>${ui.proposal?'Mind Factory / Unsaved proposal':impactCurrent(project,d)&&d.selectedAlternativeId===a.id?'Applied model impact':'Ghost / Alternative preview'}</small><h3>${esc(a.title)}</h3><p>${esc(a.consequences)}</p></div><div class="r-actions">${ui.proposal?btn('edit-proposal','Review & edit proposal','gold'):`<button type="button" class="r-btn" data-d-edit-option="${a.id}" data-step="2">Edit impact</button>${d.selectedAlternativeId!==a.id?`<button type="button" class="r-btn gold" data-d-choose="${a.id}">Use as working choice</button>`:impactCurrent(project,d)?'<span class="d-status accepted">Applied to Chapters 4 / 5</span>':btn('apply-impact','Review & apply model changes','gold')}`}${ui.proposal?btn('dismiss-proposal','Dismiss'):''}</div></section>`:''}<div class="d-map-tools"><div class="r-layer-buttons">${[['requirement','Requirements'],['driver','Quality drivers'],['alternative','Alternative'],['responsibility','Responsibilities']].map(([id,t])=>`<button type="button" data-d-layer="${id}" aria-pressed="${ui.layers.includes(id)}">${t}</button>`).join('')}</div><div class="r-map-actions">${btn('base','Reference relationships','','aria-pressed="'+ui.base+'"')}${btn('flow',icon(ui.flow?'pause':'play')+(ui.flow?'Pause impact trace':'Trace impact'),'','aria-pressed="'+ui.flow+'"')}</div></div><div id="d-map-viewport" class="r-map-viewport" tabindex="0" aria-label="Decision impact map. Scroll to explore relationships."><svg id="d-map" role="group" aria-label="Live decision impact map"></svg></div><div class="r-map-caption"><span>Green: traceability · Grey: reference · Gold dashes: proposed impact</span><span id="d-map-count"></span></div><div class="d-impact-register"><h3>Proposed responsibility relationships</h3>${a?.relationships.map(e=>`<button type="button" data-d-node="responsibility:${e.from}"><b>${esc(projectResponsibilities(project).find(r=>r.id===e.from)?.title)} → ${esc(projectResponsibilities(project).find(r=>r.id===e.to)?.title)}</b><span>${esc(e.label)}</span></button>`).join('')||'<p>No relationship changes described yet.</p>'}<p class="r-note">Tracing explains decision dependencies. It does not simulate execution time or prove that a quality target is met.</p></div></article>`}
function mapData(){const d=decision(),a=option(),ns=[],es=[];if(!d||!a)return {nodes:ns,edges:es};const add=(kind,id,title,sub,record)=>{if(!ns.some(n=>n.key===kind+':'+id))ns.push({key:kind+':'+id,kind,id,title,sub,record})};for(const id of d.requirementIds){const r=project.artefacts.find(r=>r.id===id);if(r)add('requirement',id,r.title,id,r)}for(const id of d.driverIds){const q=project.quality.drivers.find(q=>q.id===id);if(!q)continue;add('driver',id,q.title,id+' · '+q.priority,q);for(const r of q.requirementIds)es.push({from:'requirement:'+r,to:'driver:'+id,label:'motivates'});es.push({from:'driver:'+id,to:'alternative:'+(a.id||'GHOST'),label:a.assessments[id]?.effect||'unknown'})}add('alternative',a.id||'GHOST',a.title,d.id+' / '+(a.id||'GHOST'),a);for(const id of a.responsibilityIds){const r=projectResponsibilities(project).find(r=>r.id===id);if(r){add('responsibility',id,r.title,'Application responsibility',r);es.push({from:'alternative:'+(a.id||'GHOST'),to:'responsibility:'+id,label:'affects'})}}if(ui.base)for(const e of referenceEdges)if(a.responsibilityIds.includes(e.from)&&a.responsibilityIds.includes(e.to))es.push({from:'responsibility:'+e.from,to:'responsibility:'+e.to,label:e.label,reference:true});for(const e of a.relationships)es.push({from:'responsibility:'+e.from,to:'responsibility:'+e.to,label:e.label,impact:true,applied:!ui.proposal&&impactCurrent(project,d)&&d.selectedAlternativeId===a.id});const visible=ns.filter(n=>ui.layers.includes(n.kind)),keys=new Set(visible.map(n=>n.key));return {nodes:visible,edges:es.filter(e=>keys.has(e.from)&&keys.has(e.to))};}
function wrap(value,max,lines=3){const words=String(value).split(/\s+/).flatMap(w=>w.match(new RegExp('.{1,'+max+'}','g'))||[]),rows=[];let row='';for(const w of words){if((row+' '+w).trim().length>max&&row){rows.push(row);row=w}else row=(row+' '+w).trim()}if(row)rows.push(row);return rows.slice(0,lines).map((r,i)=>i===lines-1&&rows.length>lines?r.slice(0,max-1)+'…':r)}
function drawMap(){const svg=$('#d-map'),view=$('#d-map-viewport');if(!svg)return;const data=mapData(),mobile=matchMedia('(max-width:700px)').matches,groups=['requirement','driver','alternative','responsibility'].filter(k=>data.nodes.some(n=>n.kind===k)),w=mobile?Math.max(160,Math.min(244,view.clientWidth-85)):Math.max(140,Math.min(220,(view.clientWidth-100-Math.max(0,groups.length-1)*28)/Math.max(1,groups.length))),pos=new Map(),labels=[];let top=48;groups.forEach((k,col)=>{const rows=data.nodes.filter(n=>n.kind===k),x=mobile?18:22+col*(w+28);labels.push({kind:k,x,y:mobile?top-18:26});rows.forEach((n,i)=>pos.set(n.key,{x,y:(mobile?top:52)+i*157}));if(mobile)top+=rows.length*157+35});const width=mobile?view.clientWidth:Math.max(400,100+groups.length*w+Math.max(0,groups.length-1)*28),height=mobile?Math.max(350,top):Math.max(400,...[...pos.values()].map(n=>n.y+150)),focus=ui.node||'alternative:'+(option()?.id||'GHOST'),near=new Set([focus]);data.edges.filter(e=>e.from===focus||e.to===focus).forEach(e=>{near.add(e.from);near.add(e.to)});svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.style.width=width+'px';svg.style.height=height+'px';svg.innerHTML=`<defs><marker id="d-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path class="d-marker" d="M1 1L6 3.5L1 6"/></marker></defs>${labels.map(l=>`<text x="${l.x}" y="${l.y}" class="d-lane">${{requirement:'Requirements',driver:'Quality drivers',alternative:'Alternative',responsibility:'Responsibilities'}[l.kind]}</text>`).join('')}${data.edges.map((e,i)=>{const a=pos.get(e.from),b=pos.get(e.to),same=mobile||a.x===b.x,c=same?Math.min(width-8,a.x+w+35+(i%3)*9):a.x+w+14,path=same?`M${a.x+w} ${a.y+62} C${c} ${a.y+62},${c} ${b.y+62},${b.x+w} ${b.y+62}`:`M${a.x+w} ${a.y+62} C${c} ${a.y+62},${b.x-14} ${b.y+62},${b.x} ${b.y+62}`;return `<path class="d-edge ${e.reference?'reference':''} ${e.impact?'impact':''} ${e.applied?'applied':''} ${near.has(e.from)&&near.has(e.to)?'active':''}" d="${path}" marker-end="url(#d-arrow)"><title>${esc(e.label)}</title></path>${ui.flow&&!e.reference?`<circle class="d-flow ${e.impact?'impact':''}" r="3"><animateMotion path="${path}" dur="${2.3+i%3/3}s" repeatCount="indefinite"/></circle>`:''}`}).join('')}${data.nodes.map(n=>{const a=pos.get(n.key),isAlt=n.kind==='alternative',applied=isAlt&&!ui.proposal&&impactCurrent(project,decision())&&decision().selectedAlternativeId===n.id;return `<g class="d-node ${isAlt&&!applied?'ghost':''} ${n.key===focus?'selected':''} ${near.has(n.key)?'related':'muted'}" transform="translate(${a.x},${a.y})" role="button" tabindex="0" aria-label="${esc(n.sub+' '+n.title)}" aria-pressed="${n.key===focus}" data-d-node="${n.key}" data-d-insight="${n.key}"><title>${esc(n.title)}</title><rect width="${w}" height="128" rx="8"/><text x="12" y="21" class="d-node-id">${esc(n.kind==='responsibility'?'Application':n.sub)}</text>${wrap(n.title,Math.floor((w-24)/7.3)).map((t,i)=>`<text x="12" y="${46+i*18}" class="d-node-title">${esc(t)}</text>`).join('')}<text x="12" y="112" class="d-node-state">${isAlt?applied?'Applied impact':'Preview only':n.kind==='driver'?EFFECTS.find(e=>e[0]===option()?.assessments[n.id]?.effect)?.[1]||'Needs evidence':n.kind==='responsibility'?'Inspect impact':n.record.confirmed?'Confirmed':'Unconfirmed source'}</text></g>`}).join('')}`;$('#d-map-count').textContent=data.nodes.length+' objects · '+data.edges.length+' links';$('#d-map-empty')?.remove();if(!data.nodes.length){const p=document.createElement('p');p.id='d-map-empty';p.className='r-empty';p.textContent=option()?'Reveal a layer to see the model.':'Add an alternative to preview its impact.';view.append(p)}}
function contextRecord(key){const [kind,id]=key.split(':');return kind==='alternative'?(ui.proposal?.record.id===id?ui.proposal.record:decision()?.alternatives.find(a=>a.id===id)||option()):kind==='driver'?project.quality.drivers.find(q=>q.id===id):kind==='responsibility'?projectResponsibilities(project).find(r=>r.id===id):project.artefacts.find(r=>r.id===id);}
function inspector(){const d=decision(),a=option(),g=decisionGuidance(project,d,a,ui.tab);if(ui.node&&!ui.node.startsWith('alternative:'))return contextInspector(ui.node);return `<header class="r-inspector-head"><span>${icon('cursor')}Decision lens</span><small>${ui.tab}</small></header><div class="r-inspector-body">${btn('back','Back to workspace','r-mobile-return')}${d?`<p class="r-kicker">${d.id} / Revision ${d.revision}</p>${stateBadge(d)}<h2>${a?esc(a.title):'Explore an alternative'}</h2>${a?`<p class="d-preview-label">${ui.proposal?'Unsaved ghost proposal':d.selectedAlternativeId===a.id?'Current working choice':'Alternative preview'}</p><p>${esc(a.summary)}</p><h3>Consequences</h3><p>${esc(a.consequences||'Not described yet')}</p><h3>Architectural approach</h3><p>${esc(a.pattern||'Not recorded')}</p><h3>Anti-pattern to avoid</h3><p>${esc(a.antiPattern||'Explore a failure boundary with Mind Factory.')}</p><div class="r-actions">${ui.proposal?btn('edit-proposal','Review & edit proposal','gold'):`<button type="button" class="r-btn" data-d-edit-option="${a.id}">Edit alternative</button>`}</div><h3>Quality implications</h3><div class="d-lens-drivers">${d.driverIds.map(id=>{const c=criterion(project,d,id);return c?`<button type="button" data-d-node="driver:${id}"><b>${id} · ${esc(c.title)}</b>${effect(a.assessments[id])}<small>${esc(c.measure)}</small></button>`:''}).join('')}</div><h3>Affected responsibilities</h3><div class="d-source-list">${a.responsibilityIds.map(id=>`<a href="/?chapter=4&object=${id}">${esc(projectResponsibilities(project).find(r=>r.id===id)?.title||id)} ${icon('arrow')}</a>`).join('')}</div>`:''}${decisionSourceChanged(project,d)?'<div class="r-error">Inputs changed. Revise the comparison before accepting or applying this decision.</div>':''}<h3>Governance</h3><p>${governanceLabel(d,project)}</p>`:'<h2>Frame a choice with consequences.</h2>'}${evidenceContextHTML(project,d?.id,ui.tab)}<div class="r-attention"><p class="r-kicker">A useful next thought</p><p>${esc(g.attention)}</p><small>${esc(g.next)}</small>${btn('mind',icon('spark')+'Explore a ghost proposal','gold')}</div></div>`}
function contextInspector(key){const c=contextRecord(key),d=decision(),a=option(),[kind,id]=key.split(':');if(!c)return '';const q=kind==='driver'?criterion(project,d,id):null;return `<header class="r-inspector-head"><span>${icon('cursor')}Context lens</span><small>${ui.tab}</small></header><div class="r-inspector-body">${btn('back','Back to workspace','r-mobile-return')}<p class="r-kicker">${kind} / ${id}</p><h2>${esc(c.title)}</h2><p>${esc(q?q.measure:c.description)}</p>${q?`${effect(a?.assessments[id])}<p>${esc(a?.assessments[id]?.reason||'Comparison not recorded.')}</p><h3>Evidence / basis</h3><p>${esc(a?.assessments[id]?.evidence||'This judgement needs supporting evidence.')}</p>`:`<h3>Decision consequence</h3><p>${esc(a?.consequences||d.context)}</p>`}<p>${d.id} · ${esc(d.question)}</p><div class="r-actions">${btn('inspect-alternative','Return to alternative')}<a class="r-btn" href="${kind==='driver'?'/?chapter=2&tab=model&driver='+id:kind==='responsibility'?'/?chapter=4&object='+id:'/?chapter=1&tab=work&artefact='+id}">Open source ${icon('arrow')}</a></div><div class="r-attention"><p>Review the effects across all alternatives when this input changes.</p>${btn('sol','Act with Sol')}</div></div>`}
function validation(){const fs=decisionFindings(project),errors=fs.filter(f=>f.level==='error'),shown=ui.filter==='all'?fs:ui.filter==='review'?fs.filter(f=>f.level!=='error'):errors;return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">Decision revision ${project.decisions.version}</p><h2>Can the choice be explained?</h2></div>${btn('run-checks','Run checks','primary')}</div><p>Check rationale, comparison evidence, source links, conflicts, and unresolved assumptions.</p><div class="r-validation-stats"><div><b>${errors.length}</b><span>Content and conflict gaps</span></div><div><b>${fs.length-errors.length}</b><span>Assumptions and review items</span></div></div><p class="r-review-state">${decisionReviewCurrent(project)?'Checks recorded for the current requirements, quality drivers, and decisions.':'Changes require a fresh review.'} These checks do not grant governance approval.</p><div class="r-filter-tabs">${[['gaps','Content gaps'],['review','Assumptions & review'],['all','All findings']].map(([id,t])=>`<button type="button" data-d-filter="${id}" aria-pressed="${ui.filter===id}">${t}</button>`).join('')}</div><div class="f-findings">${shown.map(f=>`<article class="r-finding"><span class="r-finding-icon ${f.level}">${f.level==='error'?'!':'○'}</span><div><small>${f.decisionId}</small><h3>${esc(f.title)}</h3><p>${esc(f.detail)}</p></div><button type="button" class="r-btn" data-d-fix="${f.id}">Review ${icon('arrow')}</button></article>`).join('')||'<div class="r-empty"><h3>No findings in this category.</h3><p>Review the remaining categories before handoff.</p></div>'}</div></article>`}
function output(){const ds=project.decisions.records,accepted=ds.filter(d=>decisionCurrent(project,d));return `<article class="r-card"><div class="r-card-head"><div><p class="r-kicker">Chapter 3 / Decision register</p><h2>A reasoned basis for the application model</h2></div><span class="d-status ${decisionHandoffCurrent(project)?'accepted':'draft'}">${decisionHandoffCurrent(project)?'Current handoff':'Working revision'}</span></div><p>${accepted.length} current architect-accepted decisions · ${ds.filter(d=>impactCurrent(project,d)).length} applied impacts · ${decisionFindings(project).length} open findings.</p><div class="r-actions">${btn('export-md','Export decision register','primary')}${btn('export-json','Export shared project')}</div><div class="d-output-list">${ds.map(d=>`<button type="button" data-d-select="${d.id}" data-stage="record"><span><small>${d.id} · Revision ${d.revision}</small><b>${esc(d.question)}</b><small>${chosen(d)?esc(chosen(d).title):'No choice recorded'}</small></span>${stateBadge(d)}</button>`).join('')}</div><section class="r-handoff"><p class="r-kicker">What comes next / Chapters 4 and 5</p><h3>Carry the decision and its reasoning together.</h3><p>Accepted decisions appear on the affected responsibilities and their physical implementations. Only explicitly applied, current impacts add relationships to the model.</p>${btn('handoff','Review & carry forward','gold')}<div class="r-actions"><a class="r-btn" href="/?chapter=4">Open logical application ${icon('arrow')}</a><a class="r-btn" href="/?chapter=5">Open application realisation ${icon('arrow')}</a></div></section></article>`}
function empty(){return `<article class="r-card r-empty"><h2>Begin with a design question.</h2><p>Link its requirements and quality drivers, then compare alternatives.</p>${btn('new-question','Create a question','primary')}</article>`}
function field(label,name,value='',area=false,attrs=''){return `<label class="r-field" for="d-field-${name}"><span>${label}</span>${area?`<textarea id="d-field-${name}" name="${name}" rows="3" maxlength="4000" ${attrs}>${esc(value)}</textarea>`:`<input id="d-field-${name}" name="${name}" value="${esc(value)}" ${attrs.includes('maxlength')?'':'maxlength="4000"'} ${attrs}>`}</label>`}
function dialog(title,body,kind){if(presentAssistant(kind,title,body))return;hideTip();ui.lastFocus=document.activeElement;ui.modal=kind;ui.dirty=false;ui.flow=false;$('#d-dialog-host').innerHTML=`<dialog class="r-dialog d-dialog" aria-labelledby="d-dialog-title"><header><div><p class="r-kicker">Chapter 03 / ${ui.tab}</p><h2 id="d-dialog-title">${title}</h2></div>${btn('close',icon('close'),'icon-only','aria-label="Close dialog"')}</header><div id="d-form-error" class="r-error" role="alert" hidden></div>${body}<div class="r-discard d-discard" id="d-discard" hidden><p>Discard your unsaved changes?</p>${btn('keep','Keep editing')}${btn('discard','Discard changes')}</div></dialog>`;const el=$('.d-dialog');el.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});refineAssistantDialog(el,kind);el.showModal();(el.querySelector('input:not([type=checkbox]),select,textarea')||el.querySelector('button')).focus()}
function closeDialog(force=false){if(ui.busy&&!force)return;if(ui.dirty&&!force){$('#d-discard').hidden=false;$('#d-discard').scrollIntoView({block:'nearest'});$('#d-discard button').focus();return}ui.modal=null;ui.dirty=false;$('.d-dialog')?.close();if($('#d-dialog-host'))$('#d-dialog-host').innerHTML='';if(ui.lastFocus?.isConnected)ui.lastFocus.focus()}
function steps(names){return `<nav class="d-form-steps" aria-label="Editing steps">${names.map((t,i)=>`<button type="button" data-d-step="${i}" aria-pressed="${ui.step===i}"><span>${i+1}</span>${t}</button>`).join('')}</nav>`}
function step(i){ui.step=Math.min(2,Math.max(0,i));document.querySelectorAll('[data-d-panel]').forEach(el=>el.hidden=Number(el.dataset.dPanel)!==ui.step);document.querySelectorAll('[data-d-step]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.dStep)===ui.step)));$('.d-dialog').scrollTop=0;const panel=$('[data-d-panel="'+ui.step+'"]');panel?.querySelector('input,select,textarea')?.focus({preventScroll:true})}
function editQuestion(isNew=false,initialStep=0,preset=null){const d=isNew?{topic:'custom',question:'',context:'',requirementIds:[],driverIds:[],rationale:'',assumptions:'',assumptionEvidence:'',assumptionsResolved:false,risks:'',mitigation:'',owner:'',source:'',...(preset||{})}:decision();if(!d)return;formState={id:d.id};ui.step=initialStep;dialog(isNew?'Frame a design question':'Revise '+d.id,`<form id="d-question-form">${steps(['Question','Traceability','Reasoning'])}<section data-d-panel="0"><div class="r-form-grid"><label class="r-field"><span>Decision topic</span><select name="topic">${TOPICS.map(([id,t])=>`<option value="${id}" ${d.topic===id?'selected':''}>${t}</option>`).join('')}</select></label>${field('Decision owner','owner',d.owner)}</div>${field('Design question','question',d.question,false,'required maxlength="200"')}${field('Context and decision scope','context',d.context,true)}${field('Source / project evidence','source',d.source,true)}${btn('next-step','Next: traceability '+icon('arrow'))}</section><section data-d-panel="1" hidden><fieldset class="d-choices"><legend>Source requirements</legend>${project.artefacts.filter(a=>a.type==='requirement').map(r=>`<label><input type="checkbox" name="requirementIds" value="${r.id}" ${d.requirementIds.includes(r.id)?'checked':''}><span><b>${r.id}</b> ${esc(r.title)}<small>${r.confirmed?'Confirmed':'Unconfirmed source'}</small></span></label>`).join('')}</fieldset><fieldset class="d-choices"><legend>Quality drivers / comparison criteria</legend>${project.quality.drivers.map(q=>`<label><input type="checkbox" name="driverIds" value="${q.id}" ${d.driverIds.includes(q.id)?'checked':''}><span><b>${q.id}</b> ${esc(q.title)}<small>${q.priority} · ${q.targetConfirmed?'Target confirmed':'Target assumption'}</small></span></label>`).join('')}</fieldset>${btn('next-step','Next: reasoning '+icon('arrow'))}</section><section data-d-panel="2" hidden>${field('Decision rationale — why this choice?','rationale',d.rationale,true)}${field('Assumptions','assumptions',d.assumptions,true)}${field('Evidence resolving these assumptions','assumptionEvidence',d.assumptionEvidence,true)}<label class="r-checkbox"><input type="checkbox" name="assumptionsResolved" ${d.assumptionsResolved?'checked':''}>I confirm these assumptions against the recorded evidence.</label>${field('Risks and consequences to manage','risks',d.risks,true)}${field('Risk treatment / mitigation','mitigation',d.mitigation,true)}</section><p class="d-edit-note">${d.id?'Saving creates a working revision. Earlier acceptance, governance evidence, and applied model impacts require review. The ID '+d.id+' remains unchanged.':'A stable ADR reference is assigned on save. Add at least two alternatives to compare.'}</p><div class="r-dialog-actions">${btn('close','Cancel')}<button type="submit" class="r-btn primary">Save working revision</button></div></form>`,'question');step(initialStep)}
function newOption(){const d=decision();return {title:'',summary:'',benefits:'',costs:'',consequences:'',pattern:'',antiPattern:'',responsibilityIds:[],relationships:[],assessments:Object.fromEntries(d.driverIds.map(id=>[id,{effect:'unknown',reason:'',evidence:''}]))};}
function editAlternative(id=null,initialStep=0,proposal=null){const d=decision(),a=proposal?.record||d.alternatives.find(a=>a.id===id)||newOption();formState={id:d.id,alternativeId:proposal?proposal.existingId:id};ui.step=initialStep;dialog(proposal?'Review & edit the alternative proposal':id?'Revise '+id:'Add an alternative',`<form id="d-alternative-form">${steps(['Approach','Comparison','Impact'])}<section data-d-panel="0">${field('Alternative title','title',a.title,false,'required maxlength="160"')}${field('Approach / what would we do?','summary',a.summary,true)}<div class="r-form-grid">${field('Benefits','benefits',a.benefits,true)}${field('Costs and trade-offs','costs',a.costs,true)}</div>${field('Consequences for the design','consequences',a.consequences,true)}${field('Style, pattern, or tactic','pattern',a.pattern)}${field('Anti-pattern / failure boundary to avoid','antiPattern',a.antiPattern,true)}${btn('next-step','Next: comparison '+icon('arrow'))}</section><section data-d-panel="1" hidden><div class="r-reference-note">Describe the expected effect on each quality driver, why, and the evidence or explicit analytical basis. These judgements do not prove that a numerical target is met.</div>${d.driverIds.map(id=>{const c=criterion(project,d,id),v=a.assessments[id]||{};return c?`<fieldset class="d-criterion-editor"><legend>${id} · ${esc(c.title)}</legend><p>${esc(c.measure)} · ${c.confirmed?'confirmed':'target assumption'}</p><label class="r-field"><span>Effect on ${id}</span><select name="effect:${id}">${EFFECTS.map(([key,t])=>`<option value="${key}" ${v.effect===key?'selected':''}>${t}</option>`).join('')}</select></label>${field('Reason for '+id,'reason:'+id,v.reason,true)}${field('Evidence / analytical basis for '+id,'evidence:'+id,v.evidence,true)}</fieldset>`:''}).join('')||'<p>Link quality drivers to the design question first.</p>'}${btn('next-step','Next: model impact '+icon('arrow'))}</section><section data-d-panel="2" hidden><fieldset class="d-choices"><legend>Affected responsibilities</legend>${projectResponsibilities(project).map(r=>`<label><input type="checkbox" name="responsibilityIds" value="${r.id}" ${a.responsibilityIds.includes(r.id)?'checked':''}><span>${esc(r.title)}</span></label>`).join('')}</fieldset><h3>Proposed relationships</h3><p>Describe the responsibility relationship this option would add. The existing reference model remains visible for comparison.</p><div id="d-relationship-rows">${relationshipRows(a.relationships)}</div>${btn('add-relationship','Add proposed relationship')}<p class="r-note">Selecting an endpoint also selects its responsibility. Every relationship stays a ghost until the decision is accepted and its impact explicitly applied.</p></section><p class="d-edit-note">Saving revises ${d.id}. Review the working choice again before acceptance.</p><div class="r-dialog-actions">${btn('close','Cancel')}<button type="submit" class="r-btn primary">${proposal?'Save edited proposal':'Save alternative'}</button></div></form>`,'alternative');step(initialStep)}
function relationshipRows(rows){return rows.map((e,i)=>`<div class="d-relationship-row" data-rel-row="${i}"><div class="r-form-grid">${['from','to'].map(key=>`<label class="r-field"><span>${key==='from'?'From':'To'} responsibility ${i+1}</span><select name="rel-${key}-${i}" data-rel-endpoint><option value="">Choose responsibility</option>${projectResponsibilities(project).map(r=>`<option value="${r.id}" ${e[key]===r.id?'selected':''}>${esc(r.title)}</option>`).join('')}</select></label>`).join('')}</div>${field('Relationship meaning '+(i+1),'rel-label-'+i,e.label)}<button type="button" class="r-btn" data-d-remove-rel="${i}">Remove relationship ${i+1}</button></div>`).join('')}
function collectRelationships(){const form=$('#d-alternative-form');return [...form.querySelectorAll('[data-rel-row]')].map(el=>{const i=el.dataset.relRow;return {from:form.elements['rel-from-'+i].value,to:form.elements['rel-to-'+i].value,label:form.elements['rel-label-'+i].value}})}
function showAcceptance(){const d=decision(),fs=decisionFindings(project).filter(f=>f.decisionId===d.id),gaps=fs.filter(f=>f.level==='error');dialog('Architect acceptance · '+d.id,`<form id="d-accept-form"><p><b>${esc(chosen(d)?.title||'No choice selected')}</b></p><p>${esc(d.rationale||'Rationale is missing.')}</p><div class="r-reference-note">${gaps.length} content or conflict gaps · ${fs.length-gaps.length} assumptions and review items. This records architect acceptance; governance approval remains separate.</div>${gaps.length?`<p>Resolve the content and conflict gaps before accepting this decision.</p>${btn('validate','Review findings','primary')}`:`${fs.length?'<label class="r-checkbox"><input type="checkbox" name="acknowledge" required>I acknowledge the open assumptions and review items.</label>':''}<div class="r-dialog-actions">${btn('close','Cancel')}<button type="submit" class="r-btn primary">Accept architecture decision</button></div>`}</form>`,'accept')}
function showApply(){const d=decision(),a=option();if(!a)return;const current=a.id===d.selectedAlternativeId&&decisionCurrent(project,d);formState={id:d.id,alternativeId:a.id,revision:d.revision};dialog('Review model changes · '+d.id,`<form id="d-apply-form"><p>${esc(a.title)}</p><div class="d-before-after"><div><small>Current reference</small><p>${referenceEdges.filter(e=>a.responsibilityIds.includes(e.from)&&a.responsibilityIds.includes(e.to)).map(e=>esc(e.from+' → '+e.to+': '+e.label)).join('<br>')||'No direct relationship within these selected responsibilities.'}</p></div><div><small>Proposed additions</small>${a.relationships.map(e=>`<p>${esc(e.from+' → '+e.to)}<br><b>${esc(e.label)}</b></p>`).join('')||'<p>No relationships described.</p>'}</div></div><p>Applying adds traced relationships for this decision to the application model. Physical implementations inherit the decision reference through their logical responsibility.</p>${!current?`<div class="r-reference-note">Choose, record, and accept this alternative before applying its impact.</div>${btn('record-view','Open decision record','primary')}`:`<label class="r-checkbox"><input type="checkbox" name="reviewed" required>I have reviewed these proposed relationships and their consequences.</label><div class="r-dialog-actions">${btn('close','Cancel')}<button type="submit" class="r-btn primary">Apply reviewed model changes</button></div>`}</form>`,'apply')}
function showGovernance(){const d=decision();dialog('Record governance evidence · '+d.id,`<form id="d-governance-form"><p>Record the outcome of a separate governance review. This form does not perform that review or automatically approve the architecture.</p><label class="r-field"><span>Governance outcome</span><select name="status"><option value="pending">Review pending</option><option value="approved">Approval supported by evidence</option><option value="changes_requested">Changes requested</option></select></label>${field('Reviewer / review body','reviewer',d.governance?.reviewer||'',false,'required')}${field('External review evidence / reference','evidence',d.governance?.evidence||'',true,'required')}<p class="r-note">The evidence applies to ${d.id} revision ${d.revision}. A later revision requires review.</p><div class="r-dialog-actions">${btn('close','Cancel')}<button type="submit" class="r-btn primary">Save governance evidence</button></div></form>`,'governance')}
function editConflict(id=null,pair=null){const c=project.decisions.conflicts.find(c=>c.id===id)||{decisionIds:pair||[ui.selected,project.decisions.records.find(d=>d.id!==ui.selected)?.id],title:'',resolution:'',owner:'',status:'open'};formState={conflictId:c.id};dialog(c.id?'Review '+c.id:'Record a decision conflict',`<form id="d-conflict-form"><div class="r-form-grid">${[0,1].map(i=>`<label class="r-field"><span>${i?'Second':'First'} decision</span><select name="decision${i}">${project.decisions.records.map(d=>`<option value="${d.id}" ${c.decisionIds[i]===d.id?'selected':''}>${d.id} · ${esc(d.question)}</option>`).join('')}</select></label>`).join('')}</div>${field('Conflict description','title',c.title,true,'required')}${field('Resolution / scope distinction','resolution',c.resolution,true)}${field('Resolution owner','owner',c.owner)}<label class="r-field"><span>Conflict status</span><select name="status"><option value="open">Open for review</option><option value="resolved" ${c.id&&conflictResolved(project,c)?'selected':''}>Resolved with rationale</option></select></label><div class="r-dialog-actions">${btn('close','Cancel')}<button type="submit" class="r-btn primary">Save conflict review</button></div></form>`,'conflict')}
function handoff(){const accepted=project.decisions.records.filter(d=>decisionCurrent(project,d)),fs=decisionFindings(project);dialog('Carry decisions into Chapters 4 and 5',`<form id="d-handoff-form"><p>${accepted.length} current architect-accepted decisions will carry their original ADR references, requirements, drivers, and rationale.</p><div class="r-reference-note">${fs.length} open findings travel with the project. Approval status remains explicit.</div>${!decisionReviewCurrent(project)?`<p>Run checks against the current revisions first.</p>${btn('validate','Go to validation','primary')}`:!accepted.length?`<p>Accept at least one decision before handoff.</p>${btn('record-view','Review decision record','primary')}`:`${fs.length?'<label class="r-checkbox"><input type="checkbox" name="acknowledge" required>I acknowledge the open findings that travel with these decisions.</label>':''}<div class="r-dialog-actions">${btn('close','Cancel')}<button type="submit" class="r-btn primary">Carry forward & open Chapter 4</button></div>`}</form>`,'handoff')}
function assistant(kind){const d=decision(),a=option(),g=decisionGuidance(project,d,a,ui.tab),context=ui.node?contextRecord(ui.node):null;if(kind==='mind'){if(!d){dialog('Mind Factory · Explore a design question','<p>Capture the choice you need to make, then compare its possible approaches and consequences.</p>'+btn('new-question','Frame a design question','primary'),'mind');return}dialog('Mind Factory · Explore the design space',`${evidenceAssistantLink('mind')}<p>${d.id} / ${ui.tab} · ${esc(d.question)}</p><div class="r-reference-note">${{work:'Which approach best addresses the linked quality drivers, and what would it cost?',model:'Which responsibility or relationship would change if this approach were adopted?',validate:'Which failure boundary would invalidate the reasoning or expose an unsupported assumption?',output:'Which consequences and tests must follow this decision into the application model?'}[ui.tab]}</div>${decisionPatterns(d).map(p=>`<article class="d-pattern"><small>${p.kind}</small><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><p><b>Watch for:</b> ${esc(p.antiPattern)}</p><button type="button" class="r-btn gold" data-d-pattern="${p.id}">Preview an editable ghost</button></article>`).join('')}<p class="r-note">Contextual proposals use project rules. Live-generation status is shown in Sol.</p>`,'mind');return}const actionMap={work:`${btn('edit-question','Edit decision context')}${btn('compare-view','Compare alternatives')}${ui.proposal?btn('edit-proposal','Review & edit proposal'):a?`<button type="button" class="r-btn" data-d-edit-option="${a.id}" data-step="1">Edit comparison evidence</button>`:''}${btn('record-view','Open decision record')}`,model:`${btn('flow',ui.flow?'Pause impact trace':'Trace impact')}${ui.proposal?btn('edit-proposal','Review & edit proposal'):a?`<button type="button" class="r-btn" data-d-edit-option="${a.id}" data-step="2">Edit proposed impact</button>`:''}${btn('apply-impact','Review model changes')}`,validate:`${btn('run-checks','Run current checks','primary')}${btn('record-view','Review the decision')}`,output:`${btn('export-md','Export decision register')}${btn('handoff','Review handoff','gold')}${btn('governance','Record governance review')}`};dialog('Sol · Act on this decision',`${evidenceAssistantLink('sol')}<p>${d?d.id:'Project'} / ${ui.tab} · ${esc(context?.title||a?.title||d?.question||'Decision context')}</p><div class="r-reference-note">${esc(g.next)}</div><p>${esc(g.attention)}</p><div class="r-menu-actions">${d?actionMap[ui.tab]:btn('new-question','Create a design question','primary')}</div>`,'sol')}
function previewPattern(id){const pattern=decisionPatterns(decision()).find(p=>p.id===id);if(!pattern)return;const proposal=proposedAlternative(project,decision(),pattern);if(proposal.existingId)proposal.record.consequences+=' Verify this approach under a repeated request and a partial dependency failure.';closeDialog(true);ui.proposal=proposal;ui.node=null;ui.tab='model';render();toast('Unsaved alternative preview. Review and edit before saving.')}
function selectDecision(id,stage=null){if(!project.decisions.records.some(d=>d.id===id))return;ui.selected=id;ui.alternative=null;ui.compare=[];ui.proposal=null;ui.node=null;syncSelection();if(stage){ui.tab='work';ui.stage=stage}render()}
function navigate(tab,stage=null){if(ui.modal)closeDialog(true);ui.tab=tab;if(stage)ui.stage=stage;ui.node=null;ui.flow=false;render();$('.r-tabs .active')?.focus({preventScroll:true});$('.r-surface')?.scrollIntoView({block:'start'})}
function next(id=null){const m=decisionMilestones(project).find(m=>m.id===id)||decisionMilestones(project).find(m=>!m.done);if(!m){location.href=projectURL('/?chapter=4');return}navigate(m.tab,m.stage||null)}
function selectNode(key){if(key.startsWith('alternative:')){ui.node=null}else ui.node=key;hideTip();drawMap();$('#d-inspector').innerHTML=inspector();refineWorkspace(ui.tab,{chapter:3,id:ui.node&&!ui.node.startsWith('alternative:')?ui.node.split(':')[1]:ui.selected});if(ui.tab!=='model')openContextPanel();}
async function download(markdown=false){try{const file=await exportProject(3,markdown?'md':'json');toast('Export prepared · '+file.filename+' · '+file.bytes.toLocaleString()+' bytes.')}catch(e){toast(e.message)}}
function fix(id){const f=decisionFindings(project).find(f=>f.id===id);if(!f)return;if(f.code==='intake'){navigate('work','inputs');return}if(f.code==='empty'){editQuestion(true);return}ui.selected=f.decisionId;ui.node=null;ui.proposal=null;syncSelection();render();if(f.conflictId)return editConflict(f.conflictId);if(f.pair)return editConflict(null,f.pair);if(f.alternativeId)return editAlternative(f.alternativeId,f.driverId?1:f.code.startsWith('impact-')?2:0);if(['choice','alternatives'].includes(f.code)){navigate('work','compare');return}if(f.code==='impact'){ui.alternative=decision().selectedAlternativeId;navigate('model');return}if(f.code==='governance')return showGovernance();if(['driver-assumptions','requirement-assumptions'].includes(f.code)){navigate('work','inputs');return}editQuestion(false,['rationale','assumptions','risks','anti-pattern'].includes(f.code)?2:['links','broken-links'].includes(f.code)?1:0)}
function hideTip(){clearTimeout(tipTimer);if($('#cursor-tip'))$('#cursor-tip').hidden=true}
function showTip(el,event){if(!ui.cursor||ui.modal||matchMedia('(max-width:700px)').matches||event?.pointerType==='touch')return;clearTimeout(tipTimer);tipTimer=setTimeout(()=>{const key=el.dataset.dInsight,c=contextRecord(key);if(!c)return;const kind=key.split(':')[0],d=decision(),a=kind==='alternative'?c:option(),g=decisionGuidance(project,d,a,ui.tab),q=kind==='driver'?criterion(project,d,c.id):null;const tip=$('#cursor-tip');tip.className='r-cursor-tip d-cursor-tip';tip.innerHTML=`<small>CHAPTER 03 / ${ui.tab.toUpperCase()} · ${esc(c.id||'GHOST')}</small><h3>${esc(c.title)}</h3><p>${esc(kind==='alternative'?g.explanation:q?q.measure:c.description)}</p><p class="r-tip-attention">${esc(kind==='alternative'?'Consequence: '+g.consequence:kind==='driver'?a?.assessments[c.id]?.reason||'Compare this driver across the alternatives.':'This object is affected by '+d.id+'. '+(a?.consequences||''))}</p><small>${esc(g.next)} Select for context and editable ghost proposals.</small>`;tip.innerHTML+=`<small>${esc(evidenceCursorText(project,kind==='alternative'?d?.id:c.id))}</small>`;tip.hidden=false;const r=el.getBoundingClientRect(),x=event?.clientX??r.left+r.width/2,y=event?.clientY??r.top+r.height/2;tip.style.left=Math.max(8,Math.min(innerWidth-348,x+14))+'px';tip.style.top=Math.max(8,Math.min(innerHeight-tip.offsetHeight-8,y+14))+'px'},300)}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-d-node]');if(!b||b.disabled||ui.busy)return;
 if(b.dataset.dTab)return navigate(b.dataset.dTab);
 if(b.dataset.dComparisonView){ui.comparisonView=b.dataset.dComparisonView;render();return}
 if(b.dataset.dStage){ui.stage=b.dataset.dStage;ui.node=null;render();return}
 if(b.dataset.dSelect)return selectDecision(b.dataset.dSelect,b.dataset.stage);
 if(b.dataset.dMilestone)return next(b.dataset.dMilestone);
 if(b.dataset.dStep!==undefined)return step(Number(b.dataset.dStep));
 if(b.dataset.dEditOption)return editAlternative(b.dataset.dEditOption,Number(b.dataset.step||0));
 if(b.dataset.dChoose){if(await send('choose',{id:ui.selected,alternativeId:b.dataset.dChoose},'Working choice saved. Record the rationale before acceptance.')){ui.alternative=b.dataset.dChoose;render()}return}
 if(b.dataset.dPreview){ui.alternative=b.dataset.dPreview;ui.proposal=null;navigate('model');return}
 if(b.dataset.dMapOption){ui.alternative=b.dataset.dMapOption;ui.proposal=null;ui.node=null;render();return}
 if(b.hasAttribute('data-d-layers-all')){ui.layers=ui.layers.length===chapterPerspectives[3].length?[]:chapterPerspectives[3].map(l=>l[0]);ui.tab='model';ui.menu=false;render();return}
  if(b.dataset.dLayer){ui.tab='model';ui.menu=false;ui.layers=ui.layers.includes(b.dataset.dLayer)?ui.layers.filter(x=>x!==b.dataset.dLayer):[...ui.layers,b.dataset.dLayer];render();return}
 if(b.dataset.dNode)return selectNode(b.dataset.dNode);
 if(b.dataset.dPattern)return previewPattern(b.dataset.dPattern);
 if(b.dataset.dFilter){ui.filter=b.dataset.dFilter;render();return}
 if(b.dataset.dFix)return fix(b.dataset.dFix);
 if(b.dataset.dConflict)return editConflict(b.dataset.dConflict);
 if(b.dataset.dRemoveRel!==undefined){const rows=collectRelationships();rows.splice(Number(b.dataset.dRemoveRel),1);$('#d-relationship-rows').innerHTML=relationshipRows(rows);ui.dirty=true;return}
 switch(b.dataset.dAction){
  case'reload':load();break;case'menu':ui.menu=!ui.menu;render();break;case'next':next();break;
  case'new-question':editQuestion(true);break;case'edit-question':editQuestion(false,ui.stage==='record'?2:0);break;case'new-alternative':editAlternative();break;
  case'review-inputs':await send('intake',{},'Current requirements and quality drivers reviewed.');break;
  case'next-step':step(ui.step+1);break;case'add-relationship':{const rows=collectRelationships();if(rows.length>=12){toast('This prototype supports 12 relationships per alternative.');break}rows.push({from:'',to:'',label:''});$('#d-relationship-rows').innerHTML=relationshipRows(rows);ui.dirty=true;break}
  case'record':await send('record',{id:ui.selected},'Decision recorded. Architect acceptance and governance remain separate.');break;
  case'accept':showAcceptance();break;case'apply-impact':showApply();break;case'governance':showGovernance();break;
  case'new-conflict':if(project.decisions.records.length<2){toast('Create a second decision before recording a conflict.');break}editConflict();break;
  case'supersede':dialog('Supersede '+ui.selected,`<form id="d-supersede-form"><p>The record and history will remain available. Its current model impact will become inactive.</p>${field('Reason for superseding','reason','',true,'required')}<div class="r-dialog-actions">${btn('close','Keep decision')}<button type="submit" class="r-btn danger">Supersede decision</button></div></form>`,'supersede');break;
  case'compare-view':navigate('work','compare');break;case'record-view':navigate('work','record');break;case'model':ui.alternative=decision()?.selectedAlternativeId||ui.alternative;navigate('model');break;case'validate':navigate('validate');break;
  case'run-checks':ui.tab='validate';await send('review',{},'Checks recorded for the current project revisions.');break;
  case'flow':if(ui.modal)closeDialog(true);ui.flow=!ui.flow;render();break;case'base':ui.base=!ui.base;render();break;case'wide':ui.wide=!ui.wide;render();break;
  case'cursor':ui.cursor=!ui.cursor;saveCursorPreference(ui.cursor);render();break;case'sol':assistant('sol');break;case'mind':assistant('mind');break;
  case'edit-proposal':editAlternative(ui.proposal.existingId,0,ui.proposal);break;case'dismiss-proposal':ui.proposal=null;render();toast('Proposal dismissed. The saved model is unchanged.');break;
  case'inspect-alternative':ui.node=null;render();break;case'back':closeContextPanel();break;
  case'export-md':download(true);break;case'export-json':download(false);break;case'handoff':handoff();break;
  case'close':closeDialog();break;case'keep':$('#d-discard').hidden=true;break;case'discard':closeDialog(true);break;
  case'refresh':try{project=(await store.load()).document;(()=>{const message=$('#d-form-error')||$('#d-page-error');message.hidden=false;message.textContent='Latest project loaded. Your form values are preserved. Review them before saving again.'})()}catch(e){toast(e.message)}break;
  case'about':dialog('Choices with a continuous trail',`<p>Chapter 3 compares alternatives against the project’s actual requirements and quality drivers. Named effects, reasons, and evidence make the comparison explicit.</p><p>A working choice is a draft. Recording captures its rationale. Architect acceptance allows an explicit review of proposed model changes. Governance approval is recorded separately against external review evidence.</p><p>Revisions retain the ADR reference and decision history. Changed sources invalidate current impacts and require renewed review.</p><p>Cursor, Sol, and Mind Factory use project rules. No external LLM, payment service, or live bank integration is connected.</p>`,'about');break;
 }
});
document.addEventListener('submit',async e=>{if(!e.target.closest('.d-dialog'))return;e.preventDefault();const form=e.target,fd=new FormData(form),raw=Object.fromEntries(fd);
 if(form.id==='d-question-form'){Object.assign(raw,{id:formState.id,requirementIds:fd.getAll('requirementIds'),driverIds:fd.getAll('driverIds'),assumptionsResolved:form.elements.assumptionsResolved.checked});if(await send('save',raw,'Working revision saved with its stable ADR reference.')){if(!formState.id)ui.stage='compare';render()}}
 if(form.id==='d-alternative-form'){raw.id=formState.id;raw.alternativeId=formState.alternativeId;raw.responsibilityIds=fd.getAll('responsibilityIds');raw.relationships=collectRelationships().filter(r=>r.from||r.to||r.label.trim());raw.assessments=Object.fromEntries(decision().driverIds.map(id=>[id,{effect:fd.get('effect:'+id),reason:fd.get('reason:'+id),evidence:fd.get('evidence:'+id)}]));await send('alternative',raw,'Alternative saved. Review the working choice against the updated comparison.')}
 if(form.id==='d-accept-form')await send('accept',{id:ui.selected,acknowledge:form.elements.acknowledge?.checked===true},'Architect acceptance recorded. Governance approval remains separate.');
 if(form.id==='d-apply-form')await send('apply-impact',formState,'Reviewed model relationships applied to the current decision.');
 if(form.id==='d-governance-form')await send('governance',{id:ui.selected,...raw},'External governance review evidence recorded.');
 if(form.id==='d-conflict-form')await send('conflict',{...raw,conflictId:formState.conflictId,decisionIds:[raw.decision0,raw.decision1]},'Decision conflict review saved.');
 if(form.id==='d-supersede-form')await send('supersede',{id:ui.selected,reason:raw.reason},'Decision superseded; historical reasoning retained.');
 if(form.id==='d-handoff-form'&&await send('handoff',{acknowledge:form.elements.acknowledge?.checked===true},'Accepted decisions carried into the application model.'))location.href=projectURL('/?chapter=4');
});
document.addEventListener('input',e=>{if(e.target.closest('.d-dialog form')){ui.dirty=true;if(e.target.name==='assumptions')e.target.form.elements.assumptionsResolved.checked=false}});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-d-criterion')){ui.criterion=e.target.value;render();return}if(e.target.id==='d-question-select')selectDecision(e.target.value);if(e.target.dataset.dCompare!==undefined){const i=Number(e.target.dataset.dCompare);ui.compare[i]=e.target.value;if(ui.compare[0]===ui.compare[1])ui.compare[1-i]=decision().alternatives.find(a=>a.id!==e.target.value)?.id;render()}if(e.target.hasAttribute('data-rel-endpoint')){const checkbox=e.target.form.querySelector('input[name="responsibilityIds"][value="'+e.target.value+'"]');if(checkbox)checkbox.checked=true}});
document.addEventListener('invalid',e=>{const panel=e.target.closest('[data-d-panel]');if(panel)step(Number(panel.dataset.dPanel))},true);
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-d-insight]');if(el)showTip(el,e)});document.addEventListener('pointerout',e=>{if(e.target.closest('[data-d-insight]'))hideTip()});document.addEventListener('focusin',e=>{const el=e.target.closest('[data-d-insight]');if(el)showTip(el)});document.addEventListener('focusout',hideTip);
document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip();const n=e.target.closest('#d-map [data-d-node]');if(n&&['Enter',' '].includes(e.key)){e.preventDefault();const key=n.dataset.dNode;selectNode(key);$('#d-map [data-d-node="'+key+'"]')?.focus({preventScroll:true})}});
window.addEventListener('resize',()=>{hideTip();clearTimeout(resizeTimer);resizeTimer=setTimeout(drawMap,150)});window.addEventListener('beforeunload',e=>{if(ui.dirty||ui.busy){e.preventDefault();e.returnValue=''}});
await load();

document.addEventListener('aiw:external-project',()=>{project=store.value.document;render();});
// The Chapter 3 models edit through this page's own editors, proposals and commands.
window.aiwDecisionsPage={
  focus(id){if(project?.decisions.records.some(d=>d.id===id)){ui.selected=id;ui.alternative=null}},
  editQuestion(id){if(!project.decisions.records.some(d=>d.id===id))return;ui.selected=id;editQuestion(false)},
  newQuestion:preset=>editQuestion(true,0,preset),
  editAlternative(decisionId,altId=null){if(!project.decisions.records.some(d=>d.id===decisionId))return;ui.selected=decisionId;editAlternative(altId)},
  proposeAlternative(decisionId,record){if(!project.decisions.records.some(d=>d.id===decisionId))return;ui.selected=decisionId;editAlternative(null,0,{existingId:null,record})},
  async choose(decisionId,altId){ui.selected=decisionId;if(await send('choose',{id:decisionId,alternativeId:altId},'Working choice saved. Record the rationale before acceptance.')){ui.alternative=altId;render()}},
  get proposal(){return ui.proposal?{...ui.proposal,decisionId:ui.selected}:null},get busy(){return ui.busy}
};
